{
  "product_name": "CloudNest Diapers",
  "tagline": "Where Every Little One Feels Like They're Wrapped in a Cloud.",
  "advertisement": {
    "headline": "Finally, a Diaper Your Baby Won't Want to Take Off",
    "body_copy": "You spend every day making sure your baby is fed, safe, and loved. But have you wondered what they feel like all day long? CloudNest Diapers were engineered from the inside out with one question in mind: 'What if your baby could forget they're even wearing one?' Our ultra-soft, breathable cloud-weave fabric gently conforms to your baby's curves, while our zero-pressure waistband and leg cuffs eliminate the red marks and fussy squirming. Because comfort isn't a luxury—it's a baby's right.",
    "key_features": [
      {
        "feature": "CloudWeave Fabric",
        "description": "A featherlight, breathable top layer that feels like a second skin and wicks moisture away instantly."
      },
      {
        "feature": "Zero-Pressure Fit",
        "description": "Flexible waistband and leg cuffs that move with your baby—no digging, no red marks, no fuss."
      },
      {
        "feature": "12-Hour Dry Comfort",
        "description": "Advanced absorbent core keeps skin dry and irritation-free from morning to bedtime."
      },
      {
        "feature": "Hypoallergenic & Gentle",
        "description": "Free from chlorine, parabens, and fragrances. Dermatologist-tested for the most sensitive skin."
      },
      {
        "feature": "Wet-Comfort Indicator",
        "description": "A subtle color-change strip lets you know it's time for a change—without disturbing your baby."
      }
    ],
    "target_audience": "New and expecting parents (ages 22–45) who prioritize their baby's comfort, skin health, and well-being.",
    "tone": "Warm, reassuring, confident, and gently playful.",
    "call_to_action": "Give your little one the softest start. Try CloudNest Diapers free—your first pack is on us. Visit CloudNestDiapers.com or find us at your local baby store today.",
    "social_proof": "Rated 4.9/5 by over 12,000 parents. 'My baby actually smiles when I put one on. I don't know how, but she does.' – Melissa, mom of two",
    "sizes_available": ["Newborn (NB)", "Size 1", "Size 2", "Size 3", "Size 4", "Size 5", "Size 6"],
    "brand_colors": ["#A8D8EA", "#F9F3E9", "#FFFFFF"],
  }
}

